const sheets = $json.sheets || [];
const requests = [];
// Remove the two tabs being folded together
["Anna Call Agenda","Action Plan"].forEach(t => {
  const s = sheets.find(x => x.properties.title === t);
  if (s) requests.push({deleteSheet:{sheetId: s.properties.sheetId}});
});
// Hide War Plan, content is folded into the new tab
const wp = sheets.find(x => x.properties.title === "War Plan");
if (wp) requests.push({updateSheetProperties:{properties:{sheetId: wp.properties.sheetId, hidden:true},fields:"hidden"}});
return [{json:{requests}}];

const sheets = $json.sheets || [];
const s = sheets.find(x => x.properties.title === "Action Plan");
if (!s) return [{json:{requests:[]}}];
const sid = s.properties.sheetId;
const requests = [];

requests.push({updateSheetProperties:{properties:{sheetId:sid,gridProperties:{frozenRowCount:1}},fields:"gridProperties.frozenRowCount"}});
requests.push({repeatCell:{range:{sheetId:sid,startRowIndex:0,endRowIndex:1},cell:{userEnteredFormat:{backgroundColor:{red:0.12,green:0.16,blue:0.22},horizontalAlignment:"LEFT",verticalAlignment:"MIDDLE",wrapStrategy:"WRAP",textFormat:{foregroundColor:{red:1,green:1,blue:1},bold:true,fontSize:11}}},fields:"userEnteredFormat(backgroundColor,horizontalAlignment,verticalAlignment,wrapStrategy,textFormat)"}});
requests.push({repeatCell:{range:{sheetId:sid,startRowIndex:1,endRowIndex:80},cell:{userEnteredFormat:{verticalAlignment:"TOP",wrapStrategy:"WRAP",textFormat:{fontSize:10}}},fields:"userEnteredFormat(verticalAlignment,wrapStrategy,textFormat)"}});

[150,270,560,80,105,105].forEach((w,i) => {
  requests.push({updateDimensionProperties:{range:{sheetId:sid,dimension:"COLUMNS",startIndex:i,endIndex:i+1},properties:{pixelSize:w},fields:"pixelSize"}});
});

requests.push({repeatCell:{range:{sheetId:sid,startRowIndex:1,endRowIndex:80,startColumnIndex:1,endColumnIndex:2},cell:{userEnteredFormat:{textFormat:{bold:true,fontSize:10}}},fields:"userEnteredFormat.textFormat"}});

const blockRule = (txt,bg,fg) => ({addConditionalFormatRule:{rule:{ranges:[{sheetId:sid,startRowIndex:1,endRowIndex:80,startColumnIndex:0,endColumnIndex:1}],booleanRule:{condition:{type:"TEXT_CONTAINS",values:[{userEnteredValue:txt}]},format:{backgroundColor:bg,textFormat:{bold:true,foregroundColor:fg}}}},index:0}});
requests.push(blockRule("CRITICAL PATH",{red:0.99,green:0.82,blue:0.82},{red:0.55,green:0.06,blue:0.06}));
requests.push(blockRule("ONE EMAIL",{red:1,green:0.93,blue:0.78},{red:0.48,green:0.31,blue:0.02}));
requests.push(blockRule("DECIDE BETWEEN YOU",{red:0.83,green:0.9,blue:0.99},{red:0.05,green:0.25,blue:0.56}));
requests.push(blockRule("SETTLED",{red:0.83,green:0.94,blue:0.86},{red:0.04,green:0.35,blue:0.18}));
requests.push(blockRule("FINAL WEEKS",{red:0.91,green:0.88,blue:0.99},{red:0.32,green:0.16,blue:0.6}));
requests.push(blockRule("THINK ABOUT",{red:0.93,green:0.93,blue:0.93},{red:0.3,green:0.3,blue:0.3}));
requests.push(blockRule("CALL NOTES",{red:0.97,green:0.97,blue:0.97},{red:0.45,green:0.45,blue:0.45}));

// HARD DEADLINE rows stand out in the Item column
requests.push({addConditionalFormatRule:{rule:{ranges:[{sheetId:sid,startRowIndex:1,endRowIndex:80,startColumnIndex:1,endColumnIndex:2}],booleanRule:{condition:{type:"TEXT_CONTAINS",values:[{userEnteredValue:"HARD DEADLINE"}]},format:{backgroundColor:{red:0.99,green:0.75,blue:0.75},textFormat:{bold:true,foregroundColor:{red:0.5,green:0.03,blue:0.03}}}}},index:0}});

const ownerRule = (name,bg,fg) => ({addConditionalFormatRule:{rule:{ranges:[{sheetId:sid,startRowIndex:1,endRowIndex:80,startColumnIndex:3,endColumnIndex:4}],booleanRule:{condition:{type:"TEXT_EQ",values:[{userEnteredValue:name}]},format:{backgroundColor:bg,textFormat:{bold:true,foregroundColor:fg}}}},index:0}});
requests.push(ownerRule("Krish",{red:0.85,green:0.91,blue:0.99},{red:0.06,green:0.27,blue:0.56}));
requests.push(ownerRule("Loz",{red:0.99,green:0.89,blue:0.94},{red:0.6,green:0.09,blue:0.33}));
requests.push(ownerRule("Both",{red:0.88,green:0.89,blue:0.99},{red:0.2,green:0.19,blue:0.6}));

const statusRule = (txt,bg,fg) => ({addConditionalFormatRule:{rule:{ranges:[{sheetId:sid,startRowIndex:1,endRowIndex:80,startColumnIndex:5,endColumnIndex:6}],booleanRule:{condition:{type:"TEXT_CONTAINS",values:[{userEnteredValue:txt}]},format:{backgroundColor:bg,textFormat:{bold:true,foregroundColor:fg}}}},index:0}});
requests.push(statusRule("Locked",{red:0.83,green:0.94,blue:0.86},{red:0.04,green:0.35,blue:0.18}));
requests.push(statusRule("Done",{red:0.83,green:0.94,blue:0.86},{red:0.04,green:0.35,blue:0.18}));
requests.push(statusRule("Not started",{red:1,green:0.93,blue:0.78},{red:0.48,green:0.31,blue:0.02}));
requests.push(statusRule("Open",{red:0.99,green:0.82,blue:0.82},{red:0.55,green:0.06,blue:0.06}));

requests.push({addBanding:{bandedRange:{range:{sheetId:sid,startRowIndex:1,endRowIndex:80,startColumnIndex:0,endColumnIndex:6},rowProperties:{firstBandColor:{red:1,green:1,blue:1},secondBandColor:{red:0.975,green:0.975,blue:0.98}}}}});

requests.push({updateSheetProperties:{properties:{sheetId:sid,index:1},fields:"index"}});

return [{json:{requests}}];
